<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import type {Stage45Api,Evaluation,Page,Rating} from '../../../business-common/stage45/types'
import {date} from '../../../business-common/stage45/presentation'
import BaseCard from '../BaseCard.vue'
import AppButton from '../AppButton.vue'
import Evidence from './Evidence.vue'
const props=defineProps<{api:Stage45Api;refreshKey?:number;goodsId?:string}>()
const page=ref(1),q=ref(''),star=ref(''),data=ref<Page<Evaluation>|null>(null),summary=ref<Rating|null>(null),detail=ref<Evaluation|null>(null),loading=ref(false),error=ref('')
let ticket=0
async function load(){const run=++ticket,owner=props.api.owner();loading.value=true;error.value='';try{if(props.goodsId){const row=await props.api.read<{page:Page<Evaluation>;summary:Rating}>('/goods/'+props.goodsId+'/evaluations',{pageNumber:page.value,pageSize:20,star:star.value});if(run===ticket&&owner===props.api.owner()){data.value=row.page;summary.value=row.summary}}else{const [rows,rating]=await Promise.all([props.api.read<Page<Evaluation>>('/evaluations',{pageNumber:page.value,pageSize:20,q:q.value,star:star.value}),props.api.read<Rating>('/evaluation-summary')]);if(run===ticket&&owner===props.api.owner()){data.value=rows;summary.value=rating}}}catch(e){if(run===ticket){data.value=null;summary.value=null;error.value=e instanceof Error?e.message:'评价读取失败。'}}finally{if(run===ticket)loading.value=false}}
async function open(id:string){try{detail.value=await props.api.read<Evaluation>('/evaluations/'+id)}catch(e){error.value=e instanceof Error?e.message:'详情不可访问。'}}
function search(reset=false){if(reset){q.value='';star.value=''}page.value=1;detail.value=null;load()}
watch(()=>[props.api.owner(),props.goodsId],()=>{ticket++;data.value=null;detail.value=null;page.value=1;load()},{immediate:true});watch(()=>props.refreshKey,load);onBeforeUnmount(()=>{ticket++;data.value=null;detail.value=null})
</script>
<template><view class="s45"><BaseCard v-if="summary"><text class="section">公开评价统计</text><text class="price">{{summary.label}}</text><text class="muted">公开评价 {{summary.visibleCount}} 条 · 有效单星样本 {{summary.ratedCount}} 条</text><text class="muted">{{summary.basis}}</text></BaseCard><view v-if="!goodsId" class="search"><input v-model="q" placeholder="商品、店铺或订单" maxlength="80" @confirm="search()"/><AppButton class="s45-action" size="compact" @click="search()">查询</AppButton></view><picker :range="['全部星级','1星','2星','3星','4星','5星']" :value="star?Number(star):0" @change="star=String($event.detail.value)==='0'?'':String($event.detail.value);search()"><view class="picker">{{star?star+' 星':'全部星级'}} ▾</view></picker><AppButton class="s45-action" variant="secondary" size="compact" @click="search(true)">重置</AppButton>
<BaseCard v-if="error"><text class="error" role="alert">{{error}}</text><AppButton class="s45-action" @click="load">重新读取</AppButton></BaseCard><text v-if="loading" class="state">正在读取评价…</text>
<BaseCard v-for="row in data?.records" :key="row.id"><text class="strong">{{row.goodsName}}</text><view class="row"><text>{{row.memberName}}</text><text class="price">{{row.star==null?'历史无单星':row.star+' 星'}}</text></view><text>{{row.content||'未填写文字评价'}}</text><text v-if="!goodsId" class="muted">{{row.status==='CLOSE'?'当前已屏蔽':'公开展示'}} · {{row.storeName}}</text><text class="muted">{{date(row.createdAt)}}</text><Evidence v-if="goodsId&&row.files.length" :api="api" order-id="" purpose="EVALUATION" :model-value="row.files" readonly/><AppButton class="s45-action" v-if="!goodsId" variant="secondary" size="compact" @click="open(row.id)">查看评价与图片</AppButton></BaseCard>
<BaseCard v-if="detail"><text class="section">评价详情</text><text class="strong">{{detail.goodsName}}</text><text>{{detail.content||'未填写文字评价'}}</text><Evidence :api="api" :order-id="detail.orderId||''" purpose="EVALUATION" :model-value="detail.files" readonly/><text class="muted">商户只读查看，不能改分、删除或回复。</text><AppButton class="s45-action" variant="secondary" @click="detail=null">收起</AppButton></BaseCard>
<BaseCard v-if="data&&!data.records.length&&!loading"><text class="state">当前没有符合条件的评价。</text></BaseCard><view v-if="data" class="buttons"><AppButton class="s45-action" variant="secondary" :disabled="loading||page<=1" @click="page--;load()">上一页</AppButton><text>{{page}} 页 · {{data.total}} 条</text><AppButton class="s45-action" variant="secondary" :disabled="loading||page*data.pageSize>=data.total" @click="page++;load()">下一页</AppButton></view></view></template>
<style scoped lang="scss">@import './stage45.scss';</style>
